import androidx.annotation.DrawableRes
import com.github.damontecres.wholphin.R
import com.github.damontecres.wholphin.preferences.MediaIconStyle

internal data class MediaFlagArtwork(
    @get:DrawableRes val color: Int,
    @get:DrawableRes val monochrome: Int,
) {
    @DrawableRes
    fun resource(style: MediaIconStyle): Int? =
        when (style) {
            MediaIconStyle.ICON_COLOR -> color
            MediaIconStyle.ICON_MONOCHROME -> monochrome
            else -> null
        }
}

